{ arg out=0, freq=440, amp=0.1, gate=1, pan=0, detune=0.005, cutoff=4000, rq=0.5, lfoRate=0.2, lfoDepth=2000;
    var sig, env, filterFreq;
    env = EnvGen.ar(
        Env.adsr(0.5, 1.5, 0.7, 2.0, curve: -4),
        gate: gate,
        doneAction: 2
    );
    sig = Saw.ar(freq * (1 - detune)) + Saw.ar(freq * (1 + detune));
    filterFreq = SinOsc.kr(lfoRate).range(cutoff - lfoDepth, cutoff + lfoDepth);
    sig = LPF.ar(sig, filterFreq);
    sig = sig * amp * env;
    Out.ar(out, Pan2.ar(sig, pan));
}
